unsafe fn aptx_qmf_convolution(
    mut signal: *const aptx_filter_signal,
    mut coeffs: *const int32_t,
    mut shift: c_uint,
) -> int32_t {
    let signal_view: &aptx_filter_signal = unsafe { &*signal };
    let sig: *const int32_t =
        (&raw const signal_view.buffer as *const int32_t).offset(signal_view.pos as isize)
            as *const int32_t;
    // SAFETY: `sig` is derived from `signal_view.buffer` plus `signal_view.pos`, and this
    // function's caller/origin guarantees the convolution window contains `FILTER_TAPS`
    // contiguous `int32_t` elements starting at `sig`; `sig` is non-null because it points
    // into `signal_view.buffer`; this shared slice does not alias any live mutable reference.
    let sig_slice: &[int32_t] = unsafe { core::slice::from_raw_parts(sig, FILTER_TAPS as usize) };
    // SAFETY: `coeffs` is a caller-provided non-null pointer to at least `FILTER_TAPS`
    // contiguous coefficients; this shared slice does not alias any live mutable reference.
    let coeffs_slice: &[int32_t] =
        unsafe { core::slice::from_raw_parts(coeffs, FILTER_TAPS as usize) };

    let mut e: int64_t = 0 as int64_t;
    for (&s, &c) in sig_slice.iter().zip(coeffs_slice.iter()) {
        e += s as int64_t * c as int64_t;
    }
    return rshift64_clip24(e, shift);
